#include <cstdio>
#include <deque>
#include <vector>

// Sliding-window maximum: report the max of every window of size k in O(n)
// total. dq holds indices of a[]; values are non-increasing front to back,
// so the front index always names the current window's maximum.
std::vector<int> slidingWindowMax(const std::vector<int>& a, int k) {
    std::deque<int> dq;
    std::vector<int> out;
    for (int i = 0; i < (int)a.size(); i++) {
        while (!dq.empty() && a[dq.back()] <= a[i])
            dq.pop_back();           // dominated: can't be a future max
        dq.push_back(i);
        if (dq.front() <= i - k)
            dq.pop_front();          // fell outside the window
        if (i >= k - 1)
            out.push_back(a[dq.front()]);
    }
    return out;
}

int main() {
    std::vector<int> a = {1, 3, -1, -3, 5, 3, 6, 7};
    std::vector<int> result = slidingWindowMax(a, 3);
    for (size_t i = 0; i < result.size(); i++)
        printf("%d%s", result[i], i + 1 < result.size() ? " " : "\n");
    return 0;
}
